properties.query:
let alertWindow = 10m;
let offHoursStart = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'OffHoursStart'
    | project toint(Value));
let offHoursEnd = toscalar(
    _GetWatchlist('UAV_Threshold_List')
    | where ThresholdKey == 'OffHoursEnd'
    | project toint(Value));
let ApprovedCmds = _GetWatchlist('Approved_Mission_Command_List') | project CommandType;
UAVC4I_CL
| where TimeGenerated > ago(alertWindow)
| where hourofday(TimeGenerated) >= offHoursStart or hourofday(TimeGenerated) < offHoursEnd
| where EventType !in (ApprovedCmds)
| extend TriggerReason = strcat("C4I_야간_비인가_명령_EventType:", EventType, "_IssuedBy:", IssuedBy, "_", tostring(hourofday(TimeGenerated)), "시")
| extend Severity = "High"
| project TimeGenerated, OrderId, EventType, IssuedBy, Roe, TriggerReason, Severity
| order by TimeGenerated desc
